import {FROST,STORY,PATTERN,LESSONS,REFERENCES} from './content.js';
import {probabilities} from './engine.js';
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const visible=c=>c===' '?'␠':c==='\n'?'↵':c==='\t'?'⇥':c;
const fmt=(n,k=3)=>Number.isFinite(n)?n.toFixed(k):'—';
const S={lesson:0,data:null,busy:null,modelPending:true,text:FROST,draftText:FROST,config:{dim:24,heads:2,context:24,seed:42,split:.85},history:[],inspect:null,prompt:'Two roads',output:'',genPrompt:'Two roads',temperature:.8,topK:0,genLength:160,genSeed:123,selectedHead:0,selectedRow:-1,selectedToken:0,position:0,window:0,tokenMode:'character',tokenText:'Two roads diverged in a yellow wood',bpe:[],merges:[],toyLogits:[1,2,-1,0,1.5],toyW:-2,toyLR:.2,toySteps:0,learned:null,guess:null,selectedBlock:'x',q:[1,1],keys:[[1.5,.5],[-1,1.5],[.5,-1],[-1.5,-.7]],values:[2,5,-1,8],mask:true,queryRow:2,checked:new Set(),noticeTimer:null};
S.embedToken=0;S.draftConfig={...S.config};S.trainLR=.003;S.trainSteps=100;
let requestId=0,modelRequest=0,activeJob=0,worker;const pending=new Map();
const send=(type,data={})=>{const id=++requestId;worker.postMessage({type,...data,id});return id;};
function notice(message,error=false){$('notice').textContent=message;$('notice').className='show'+(error?' error':'');clearTimeout(S.noticeTimer);S.noticeTimer=setTimeout(()=>$('notice').className='',error?10000:5000);}
function updateStatus(){const busy=S.busy,ready=S.data&&!S.modelPending;$('model-state').textContent=busy==='train'?'Training on your device':busy==='generate'?'Generating characters':ready?(S.data.step?`Trained · ${S.data.step.toLocaleString()} steps`:'Random weights · ready'):'Creating your model';$('state-dot').className='dot '+(busy?'busy':ready?'ready':'');$('model-summary').textContent=ready?`${S.data.count.toLocaleString()} parameters · ${S.data.vocab.length} characters · ${S.data.config.heads} heads`:'A real neural network, on your device.';}
function initialize(text=S.draftText,config=S.config){S.modelPending=true;S.busy=null;activeJob=0;S.inspect=null;modelRequest=send('init',{text,config});updateStatus();}
try{worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});worker.onerror=()=>{S.busy=null;notice('The model worker could not start. Open the tutorial through a web server in a modern browser, then reload.',true);updateStatus();};worker.onmessage=({data:m})=>{
  if(m.type==='ready'){if(m.id!==modelRequest)return;S.modelPending=false;S.data=m;S.config=m.config;S.draftConfig={...m.config};S.text=m.text;S.draftText=m.text;S.history=m.history;S.output='';S.genPrompt=Array.from(m.text).slice(0,9).join('');S.prompt=S.genPrompt;S.inspect=null;S.selectedToken=0;S.embedToken=0;S.position=0;S.window=0;S.busy=null;S.learned=null;S.progress=null;S.genDistribution=null;S.genContext=null;S.selectedHead=0;S.topK=0;updateStatus();render();return;}
  if(m.type==='error'){if(m.id===modelRequest)S.modelPending=false;if(m.id===activeJob||m.id===modelRequest)S.busy=null;pending.get(m.id)?.reject(Error(m.message));pending.delete(m.id);notice(m.message,true);updateStatus();syncButtons();return;}
  if(m.type==='inspection'){const p=pending.get(m.id);pending.delete(m.id);p?.resolve(m.result);return;}
  if(m.type==='export'){download(m.snapshot);return;}
  if(m.id!==activeJob)return;
  if(m.type==='progress'){S.data.step=m.step;S.history.push({step:m.step,train:m.train,validation:m.validation});if(S.history.length>500)S.history.shift();S.progress=m;S.learned=m.witness||null;updateStatus();if(S.lesson===9)updateTraining();return;}
  if(m.type==='trained'){S.busy=null;S.data={...S.data,...m};S.history=m.history;updateStatus();if(S.lesson===9)updateTraining();syncButtons();notice(`Completed ${m.step.toLocaleString()} total optimizer steps.`);return;}
  if(m.type==='token'){S.output=m.output;S.genDistribution=m.distribution;S.genContext=m.context;S.genCompleted=m.completed;if(S.lesson===11)updateGeneration();return;}
  if(m.type==='generated'||m.type==='stopped'){S.busy=null;if(m.type==='stopped'&&m.config){S.data={...S.data,...m};S.history=m.history;}updateStatus();syncButtons();if(S.lesson===9)updateTraining();if(S.lesson===11)updateGeneration();}
};initialize();}catch(e){notice('This browser cannot create the model worker: '+e.message,true);}
function inspect(prompt){return new Promise((resolve,reject)=>{const id=send('inspect',{prompt});pending.set(id,{resolve,reject});});}
function modelGuard(){if(!S.data||S.modelPending){notice('The model is still getting ready.');return false;}return true;}
function stop(){if(!worker)return;activeJob=send('stop');S.busy=null;updateStatus();syncButtons();}
function train(steps){if(!modelGuard()||S.busy)return;const lr=Number($('train-lr')?.value||S.trainLR);S.busy='train';S.progress={completed:0,requested:steps,elapsed:0};activeJob=send('train',{steps,lr});updateStatus();syncButtons();if(S.lesson===9)updateTraining();}
function generate(length){if(!modelGuard()||S.busy)return;S.genPrompt=$('gen-prompt')?.value??S.genPrompt;S.temperature=Number($('gen-temp')?.value??S.temperature);S.topK=Number($('gen-topk')?.value??S.topK);S.genSeed=Number($('gen-seed')?.value??S.genSeed);if(!Number.isSafeInteger(S.genSeed)||S.genSeed<0||S.genSeed>4294967295){notice('Choose a whole-number sampling seed between 0 and 4294967295.',true);return;}const prompt=length===1&&S.output?S.output:S.genPrompt;if(!prompt){notice('Enter at least one character from the training vocabulary to start generation.',true);return;}if(length!==1)S.output='';S.busy='generate';activeJob=send('generate',{prompt,length,temperature:S.temperature,topK:S.topK,seed:S.genSeed+(length===1?Math.max(0,Array.from(S.output).length-Array.from(S.genPrompt).length):0)});updateStatus();syncButtons();updateGeneration();}
function download(snapshot){const blob=new Blob([JSON.stringify(snapshot)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`attention-lab-step-${snapshot.step}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Model exported with weights, text, and optimizer state.');}
function syncButtons(){document.querySelectorAll('#gen-prompt,#gen-temp,#gen-topk,#gen-length,#gen-seed').forEach(b=>b.disabled=S.busy==='generate');document.querySelectorAll('[data-idle]').forEach(b=>b.disabled=!!S.busy||S.modelPending);document.querySelectorAll('[data-stop]').forEach(b=>b.disabled=!S.busy);document.querySelectorAll('[data-ready]').forEach(b=>b.disabled=!S.data||S.modelPending);}
function go(n){if(n<0||n>=LESSONS.length)return;S.lesson=n;location.hash='lesson-'+n;render();$('sidebar').classList.remove('open');$('menu-toggle').setAttribute('aria-expanded','false');syncNavigation();window.scrollTo({top:0,behavior:'instant'});$('main').focus({preventScroll:true});}
function card(title,badge,body,dark=false){return `<section class="card${dark?' dark':''}"><div class="card-head"><h3>${title}</h3>${badge?`<span class="tag${dark?'':' green'}">${badge}</span>`:''}</div>${body}</section>`;}
function range(id,label,min,max,step,value,suffix=''){return `<div class="field"><label for="${id}">${label}<output id="${id}-out">${value}${suffix}</output></label><input type="range" id="${id}" min="${min}" max="${max}" step="${step}" value="${value}" data-suffix="${suffix}"></div>`;}
function select(id,label,options,value){return `<div class="field"><label for="${id}">${label}</label><select id="${id}">${options.map(([v,t])=>`<option value="${v}"${String(v)===String(value)?' selected':''}>${t}</option>`).join('')}</select></div>`;}
function bars(p,labels,limit=8){return p.map((x,i)=>({x,i})).sort((a,b)=>b.x-a.x).slice(0,limit).map(({x,i})=>`<div class="bar-row"><code>${esc(visible(labels[i]))}</code><div class="bar-track"><div class="bar-fill" style="width:${100*x}%"></div></div><span class="percent">${(100*x).toFixed(1)}%</span></div>`).join('');}
function tokens(chars,ids=[],selected=-1,attr=''){return chars.map((c,i)=>`<button class="token${i===selected?' active':''}" ${attr?`data-${attr}="${i}"`:''} title="${esc(JSON.stringify(c))}${ids.length?' · ID '+ids[i]:''}">${esc(visible(c))}${ids.length?`<small>${ids[i]}</small>`:''}</button>`).join('');}
function matrixRow(values){return `<div class="tensor-row">${values.map((v,i)=>`<div class="tensor-cell" title="Dimension ${i}: ${v.toFixed(7)}" style="background:${v>=0?`rgba(38,166,114,${Math.min(.72,.1+Math.abs(v)*1.7)})`:`rgba(218,137,83,${Math.min(.72,.1+Math.abs(v)*1.7)})`}">${v.toFixed(2)}</div>`).join('')}</div>`;}
function mountRange(id,callback){$(id)?.addEventListener('input',e=>{$(id+'-out').textContent=e.target.value+(e.target.dataset.suffix||'');callback(Number(e.target.value));});}
function render(){const L=LESSONS[S.lesson];$('chapter-label').textContent=String(S.lesson+1).padStart(2,'0')+' · '+L.short;$('navigation').innerHTML=LESSONS.map((x,i)=>`${x.group?`<div class="nav-group">${x.group}</div>`:''}<button class="nav-link ${S.lesson===i?'active':''}" data-go="${i}" ${S.lesson===i?'aria-current="step"':''}><span class="nav-number">${S.checked.has(i)?'✓':String(i+1).padStart(2,'0')}</span>${x.short}</button>`).join('');
  $('lesson').innerHTML=`<div class="lesson-head"><div class="eyebrow"><span class="line"></span>LESSON ${String(S.lesson+1).padStart(2,'0')} / ${LESSONS.length}</div><h1>${L.title}</h1><p class="intro">${L.intro}</p><div class="try-strip"><b>TRY THIS</b><span>${L.task}</span></div></div><div id="experiment">${views[S.lesson]()}</div><div class="concept"><div><h3>The idea to take with you</h3><p>${L.why}</p></div><div class="quiz"><strong>Check your intuition</strong><p class="small">${L.check[0]}</p><div class="quiz-options">${L.check.slice(1).map((x,i)=>`<button class="quiz-option" data-quiz="${i}">${x}</button>`).join('')}</div><p id="quiz-feedback" class="quiz-feedback" aria-live="polite"></p></div></div><details><summary>Under the hood · the technical details</summary><p>${L.technical}</p></details><div class="lesson-bottom"><button class="text-button" data-go="${S.lesson-1}" ${S.lesson===0?'disabled':''}>← Previous lesson</button><button class="btn" data-go="${S.lesson===12?9:S.lesson+1}">${S.lesson===12?'Back to your model':LESSONS[S.lesson+1].short} <span aria-hidden="true">→</span></button></div>`;
  mounts[S.lesson]?.();syncButtons();
}
const views=[],mounts=[];
views[0]=()=>`<div class="grid">${card('What comes next?','START WITH INTUITION',`<div class="overline">A CONTEXT, NOT A QUESTION</div><div class="quote">Two roads diverged<br>in a yellow <span class="blank" id="guess-word">${S.guess||'&nbsp;'}</span></div><div class="choice-row">${['wood','sky','robot','road'].map(x=>`<button class="choice ${S.guess===x?'selected':''}" data-guess="${x}">${x}</button>`).join('')}</div><div id="guess-feedback" class="small mt">${S.guess?S.guess==='wood'?'Yes — “wood” is the next word in Frost’s poem.':'A possible guess, but Frost wrote “wood”. A model is rewarded for the actual next token.':'Pick a word, then compare your guess with the original line.'}</div><div class="mini-pipeline"><span>context</span><b>→</b><span>model</span><b>→</b><span>probabilities</span><b>→</b><span>next token</span></div>`,true)}${card('Your real model','ALREADY CREATED',`<p class="muted">Behind this guide is a small transformer with random starting weights. It predicts <strong>characters</strong>, one at a time.</p><div class="stat-grid"><div class="stat"><strong>${S.data?.count.toLocaleString()||'…'}</strong><span>PARAMETERS</span></div><div class="stat"><strong>${S.config.heads}</strong><span>ATTENTION HEADS</span></div><div class="stat"><strong>${S.config.context}</strong><span>CONTEXT</span></div></div><div class="note">Follow the lessons in order, or jump to training and come back to inspect what changed.</div><div class="row mt"><button class="btn" data-go="1">Build it step by step →</button><button class="text-button" data-go="9">Try training now</button></div><p class="source-note">A genuine tiny language model, not a general-purpose assistant. No pretrained AI service is used.</p>`)} </div>`;
mounts[0]=()=>document.querySelectorAll('[data-guess]').forEach(b=>b.onclick=()=>{S.guess=b.dataset.guess;render();});
views[1]=()=>`<div class="grid">${card('The training text','EDITABLE',`${select('dataset','Choose a starting point',[['frost','Robert Frost · The Road Not Taken'],['story','Original story · The small robot'],['pattern','Repeating pattern · easy to learn'],['custom','Custom text']],S.draftText===FROST?'frost':S.draftText===STORY?'story':S.draftText===PATTERN?'pattern':'custom')}<div class="field"><label for="corpus">Your corpus <span class="muted">· 160–20,000 characters</span></label><textarea id="corpus" rows="12" spellcheck="false">${esc(S.draftText)}</textarea></div><p class="source-note">Frost: <a href="https://www.gutenberg.org/ebooks/29345" target="_blank" rel="noopener noreferrer">Mountain Interval (1916)</a>, public domain in the USA; copyright terms elsewhere vary. The original story and pattern are provided for unrestricted use.</p>`)}${card('Keep a little text unseen','DATA SPLIT',`<p class="small">Train on the first part. Evaluate on the last part. We split before creating windows, so no training window reaches into held-out text.</p>${range('split','Training share',65,90,5,Math.round(S.draftConfig.split*100),'%')}<div id="data-stats"></div><div class="subtle-divider"></div><h3>Your model recipe</h3><div class="inline-fields">${select('dim','Vector width',[[16,'16 · faster'],[24,'24 · balanced'],[32,'32 · larger']],S.draftConfig.dim)}${select('heads','Attention heads',[[1,'1 head'],[2,'2 heads'],[4,'4 heads']],S.draftConfig.heads)}${select('context','Context length',[[8,'8 chars'],[16,'16 chars'],[24,'24 chars'],[32,'32 chars']],S.draftConfig.context)}</div><div class="field"><label for="init-seed">Initialization seed</label><input id="init-seed" type="number" min="0" max="4294967295" value="${S.draftConfig.seed}"></div><p class="small">Draft settings: the current model stays unchanged until you create a fresh model.</p><button class="btn" id="create-model" data-idle>Create fresh model</button><p class="source-note">This replaces the current model with random weights and clears its training. Export it in “Generate & save” first if you want to keep it. Text stays in this browser.</p>`)} </div>`;
function updateDataStats(){const chars=Array.from(S.draftText),split=Number($('split').value)/100,cut=Math.floor(chars.length*split);$('data-stats').innerHTML=`<div class="split-strip"><div class="train" style="width:${split*100}%"></div><div class="val" style="width:${100-split*100}%"></div></div><div class="stat-grid"><div class="stat"><strong>${chars.length}</strong><span>CHARACTERS</span></div><div class="stat"><strong>${new Set(chars).size}</strong><span>VOCABULARY</span></div><div class="stat"><strong>${chars.length-cut}</strong><span>HELD OUT</span></div></div><div class="overline">HELD-OUT TEXT BEGINS</div><p class="small mono">“${esc(chars.slice(cut,cut+80).join(''))}…”</p>`;}
mounts[1]=()=>{updateDataStats();$('corpus').oninput=e=>{S.draftText=e.target.value;$('dataset').value=S.draftText===FROST?'frost':S.draftText===STORY?'story':S.draftText===PATTERN?'pattern':'custom';updateDataStats();};$('dataset').onchange=e=>{if(e.target.value==='custom')return;S.draftText={frost:FROST,story:STORY,pattern:PATTERN}[e.target.value];$('corpus').value=S.draftText;updateDataStats();};mountRange('split',v=>{S.draftConfig.split=v/100;updateDataStats();});for(const key of ['dim','heads','context'])$(key).onchange=e=>S.draftConfig[key]=Number(e.target.value);$('init-seed').oninput=e=>S.draftConfig.seed=Number(e.target.value);$('create-model').onclick=()=>{const config={dim:Number($('dim').value),heads:Number($('heads').value),context:Number($('context').value),seed:Number($('init-seed').value),split:Number($('split').value)/100};if(!Number.isSafeInteger(config.seed)||config.seed<0||config.seed>4294967295){notice('Choose a whole-number seed between 0 and 4294967295.',true);return;}initialize(S.draftText,config);syncButtons();};};
function tokenizerParts(){if(S.tokenMode==='character')return Array.from(S.tokenText);if(S.tokenMode==='word')return S.tokenText.match(/\s+|[\p{L}\p{N}]+|[^\s\p{L}\p{N}]/gu)||[];if(!S.bpe.length)S.bpe=Array.from(S.tokenText);return S.bpe;}
views[2]=()=>`<div class="grid">${card('A tokenizer workbench','ILLUSTRATION',`<div class="field"><label for="token-text">Text to tokenize</label><input id="token-text" type="text" maxlength="120" value="${esc(S.tokenText)}"></div><div class="segmented" aria-label="Tokenization example">${[['character','Characters'],['word','Words'],['bpe','Pair merges']].map(([v,t])=>`<button data-mode="${v}" class="${S.tokenMode===v?'active':''}" aria-pressed="${S.tokenMode===v}">${t}</button>`).join('')}</div><div id="token-results"></div>`)}${card('An ID is an address','NOT A MEANING',`<div id="token-detail"></div><div class="subtle-divider"></div><p class="small">Click any piece on the left. The ID tells us which row of the embedding table to retrieve.</p><div class="note">The actual model always uses characters. Switching the example tokenizer does not rebuild or change it.</div><p class="source-note">␠ = space · ↵ = newline. In this sandbox, IDs are assigned in first-appearance order; the real model sorts its vocabulary.</p>`)} </div>`;
function updateTokens(){const parts=tokenizerParts(),vocab=[...new Set(parts)],ids=parts.map(x=>vocab.indexOf(x));S.selectedToken=Math.min(S.selectedToken,Math.max(0,parts.length-1));$('token-results').innerHTML=`<div class="token-cloud">${tokens(parts,ids,S.selectedToken,'piece')}</div><p class="small">${parts.length} tokens · ${vocab.length} distinct pieces</p>${S.tokenMode==='bpe'?`<button class="btn secondary small-btn" id="merge-pair">Merge most frequent pair</button><button class="text-button" id="reset-merges" style="margin-left:14px">Reset</button><p class="source-note">${S.merges.length?S.merges.map(esc).join(' · '):'Start from individual characters. Each click learns one merge on this snippet.'}</p>`:''}`;
  const selected=parts[S.selectedToken];$('token-detail').innerHTML=selected===undefined?'<p class="small">Enter some text to see its tokens.</p>':`<div class="overline">SELECTED TOKEN</div><div class="big-token" style="color:var(--green)">${esc(visible(selected))}</div><div class="formula">${esc(JSON.stringify(selected))} → ID ${ids[S.selectedToken]}<br>embedding[${ids[S.selectedToken]}] → [ … numbers … ]</div>`;
  document.querySelectorAll('[data-piece]').forEach(b=>b.onclick=()=>{S.selectedToken=Number(b.dataset.piece);updateTokens();});if($('merge-pair'))$('merge-pair').onclick=()=>{const count=new Map();for(let i=0;i<S.bpe.length-1;i++){const key=JSON.stringify([S.bpe[i],S.bpe[i+1]]);count.set(key,(count.get(key)||0)+1);}const best=[...count].sort((a,b)=>b[1]-a[1])[0];if(!best||best[1]<2){notice('No repeated pairs remain in this snippet. Try “banana banana banana”.');return;}const [a,b]=JSON.parse(best[0]),out=[];for(let i=0;i<S.bpe.length;i++){if(S.bpe[i]===a&&S.bpe[i+1]===b){out.push(a+b);i++;}else out.push(S.bpe[i]);}S.bpe=out;S.merges.push(`${visible(a)} + ${visible(b)} → ${visible(a+b)}`);updateTokens();};if($('reset-merges'))$('reset-merges').onclick=()=>{S.bpe=Array.from(S.tokenText);S.merges=[];updateTokens();};}
mounts[2]=()=>{updateTokens();$('token-text').oninput=e=>{S.tokenText=e.target.value;S.bpe=[];S.merges=[];S.selectedToken=0;updateTokens();};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{S.tokenMode=b.dataset.mode;render();});};
views[3]=()=>!S.data?'<div class="loading">Creating training examples…</div>':`<div class="stack">${card('Slide a training window','ACTUAL DATA',`${range('window','Starting character',0,S.data.cut-S.config.context-1,1,S.window)}<div id="window-content"></div><div class="row between mt"><p class="small">Only the training portion is selectable here. Each target is one character ahead.</p><span class="tag green">T = ${S.config.context}</span></div>`)}<div class="grid equal">${card('During training','TEACHER FORCING','<p class="muted">Every position gets the true earlier characters as context. The causal mask prevents positions from seeing later inputs.</p><div class="formula">input:  [T, w, o, ␠, r, o, a, d]<br>target: [w, o, ␠, r, o, a, d, s]</div>')}${card('During generation','AUTOREGRESSIVE','<p class="muted">Only the last position’s prediction is sampled. That new character is appended and the model runs again.</p><div class="formula">Two road → s<br>Two roads → ␠<br>Two roads␠ → d</div>')}</div></div>`;
function updateWindow(){const chars=Array.from(S.text),x=chars.slice(S.window,S.window+S.config.context),y=chars.slice(S.window+1,S.window+S.config.context+1);$('window-content').innerHTML=`<div class="arrow-caption">INPUT · what each position is allowed to build on</div><div class="token-line">${x.map((c,i)=>`<div class="token">${esc(visible(c))}<small>${i}</small></div>`).join('')}</div><div class="arrow-caption">TARGET · the next character at each position</div><div class="token-line">${y.map((c,i)=>`<div class="token">${esc(visible(c))}<small>${i+1}</small></div>`).join('')}</div><p class="small mt">At position 0: <strong>${esc(JSON.stringify(x[0]))}</strong> predicts <strong>${esc(JSON.stringify(y[0]))}</strong>. At the last position: the whole input window predicts <strong>${esc(JSON.stringify(y[y.length-1]))}</strong>.</p>`;}
mounts[3]=()=>{if(!S.data)return;updateWindow();mountRange('window',v=>{S.window=v;updateWindow();});};
views[4]=()=>!S.data?'<div class="loading">Creating embeddings…</div>':`<div class="stack">${card('Token vector + position vector','LIVE MODEL',`<div class="inline-fields">${select('embed-char','Character',S.data.vocab.map((c,i)=>[i,`${visible(c)} · ID ${i}`]),S.embedToken)}${range('embed-pos','Position',0,S.config.context-1,1,S.position)}</div><div id="embedding-results" class="loading">Reading model weights…</div><p class="source-note">Green = positive · orange = negative. Each cell is one learned coordinate, rounded for display. Horizontal scrolling reveals all ${S.config.dim} dimensions.</p>`)}<div class="note">Train for a while, then return here. These are actual embedding and position weights, so they change as the model learns.</div></div>`;
async function updateEmbedding(){if(!S.data)return;const c=S.data.vocab[S.embedToken]||S.data.vocab[0],pos=S.position,tokenIndex=S.embedToken,lesson=S.lesson;try{const r=await inspect(c.repeat(pos+1));if(S.lesson!==lesson||!$('embedding-results')||S.position!==pos||S.embedToken!==tokenIndex)return;const t=r.trace;$('embedding-results').className='';$('embedding-results').innerHTML=`<div class="tensor-label">TOKEN EMBEDDING · E[${S.embedToken}] · same character, same token vector</div>${matrixRow(t.tokens.last)}<span class="equation-symbol">+</span><div class="tensor-label">POSITION EMBEDDING · P[${pos}] · depends on where it appears</div>${matrixRow(t.position.last)}<span class="equation-symbol">=</span><div class="tensor-label">INPUT REPRESENTATION · ${esc(JSON.stringify(c))} at position ${pos}</div>${matrixRow(t.x.last)}<div class="formula mt">Coordinate 0: ${fmt(t.tokens.last[0],5)} + ${fmt(t.position.last[0],5)} = ${fmt(t.x.last[0],5)}</div>`;}catch{}}
mounts[4]=()=>{if(!S.data)return;S.embedToken=Math.min(S.embedToken,S.data.vocab.length-1);updateEmbedding();$('embed-char').onchange=e=>{S.embedToken=Number(e.target.value);updateEmbedding();};mountRange('embed-pos',v=>{S.position=v;updateEmbedding();});};
views[5]=()=>`<div class="grid">${card('Move the query. Change the match.','2D SANDBOX',`<svg id="vector-canvas" class="vector-canvas" viewBox="0 0 400 310" role="img" aria-label="Draggable query and key vectors. Equivalent keyboard-accessible sliders are below."></svg><p class="source-note">Drag Q (green) or a numbered key. The controls below also work with a keyboard.</p><div class="inline-fields">${range('qx','Query x',-2,2,.05,S.q[0])}${range('qy','Query y',-2,2,.05,S.q[1])}</div><details><summary>Edit a key with the keyboard</summary><div class="mt">${select('key-index','Key',[[0,'Key 1'],[1,'Key 2'],[2,'Key 3'],[3,'Key 4']],0)}${range('kx','Key x',-2,2,.05,S.keys[0][0])}${range('ky','Key y',-2,2,.05,S.keys[0][1])}</div></details>`)}${card('From scores to a mixture','SCALED DOT PRODUCT',`${select('query-row','Query position',[[0,'1 · sees key 1'],[1,'2 · sees keys 1–2'],[2,'3 · sees keys 1–3'],[3,'4 · sees all keys']],S.queryRow)}<label class="row small"><input type="checkbox" id="causal" ${S.mask?'checked':''}> Use causal mask</label><div id="attention-math" class="mt"></div><div class="subtle-divider"></div>${range('value-edit','Value carried by key 1',-5,10,.5,S.values[0])}<p class="source-note">The keys choose where to look. The values choose what is collected. Disabling the mask here demonstrates future leakage; the real model always masks future tokens.</p>`)} </div>`;
function toyWeights(){const raw=S.keys.map(k=>(k[0]*S.q[0]+k[1]*S.q[1])/Math.sqrt(2)),masked=raw.map((x,i)=>S.mask&&i>S.queryRow?-1e9:x);return {raw,p:probabilities(masked)};}
function updateAttention(){const svg=$('vector-canvas');if(!svg)return;const center=[200,155],scale=61,pos=p=>[center[0]+p[0]*scale,center[1]-p[1]*scale];svg.innerHTML=`<defs><marker id="arrow-q" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#167657"/></marker></defs>${[-2,-1,0,1,2].map(n=>`<line x1="35" y1="${155-n*61}" x2="365" y2="${155-n*61}" stroke="${n?'#e2e9ed':'#acbac4'}"/><line x1="${200+n*61}" y1="20" x2="${200+n*61}" y2="290" stroke="${n?'#e2e9ed':'#acbac4'}"/>`).join('')}${S.keys.map((k,i)=>{const [x,y]=pos(k);return `<line x1="200" y1="155" x2="${x}" y2="${y}" stroke="#6f8a9e" stroke-width="2"/><g data-vector="${i}" class="vector-point"><circle cx="${x}" cy="${y}" r="14" fill="#d8e6ee" stroke="#6f8a9e"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="12" fill="#243f54">${i+1}</text></g>`;}).join('')}<line x1="200" y1="155" x2="${pos(S.q)[0]}" y2="${pos(S.q)[1]}" stroke="#167657" stroke-width="3" marker-end="url(#arrow-q)"/><g data-vector="q" class="vector-point"><circle cx="${pos(S.q)[0]}" cy="${pos(S.q)[1]}" r="15" fill="#167657"/><text x="${pos(S.q)[0]}" y="${pos(S.q)[1]+4}" text-anchor="middle" font-size="12" fill="white">Q</text></g><text x="370" y="151" class="svg-label">x</text><text x="209" y="19" class="svg-label">y</text>`;
  const {raw,p}=toyWeights(),sum=p.reduce((s,w,i)=>s+w*S.values[i],0);$('attention-math').innerHTML=`<div class="attention-scores">${p.map((w,i)=>`<div class="attention-score ${S.mask&&i>S.queryRow?'masked':''}"><div class="overline">KEY ${i+1}</div><b>${(w*100).toFixed(1)}%</b><small>score ${S.mask&&i>S.queryRow?'masked':raw[i].toFixed(2)}<br>value ${S.values[i]}</small></div>`).join('')}</div><div class="formula mt">score₁ = (${fmt(S.q[0],2)} × ${fmt(S.keys[0][0],2)} + ${fmt(S.q[1],2)} × ${fmt(S.keys[0][1],2)}) / √2<br>= ${raw[0].toFixed(3)}<br><br>output = Σ weightᵢ × valueᵢ<br>= <strong>${sum.toFixed(3)}</strong></div>`;
}
mounts[5]=()=>{updateAttention();mountRange('qx',v=>{S.q[0]=v;updateAttention();});mountRange('qy',v=>{S.q[1]=v;updateAttention();});mountRange('value-edit',v=>{S.values[0]=v;updateAttention();});$('query-row').onchange=e=>{S.queryRow=Number(e.target.value);updateAttention();};$('causal').onchange=e=>{S.mask=e.target.checked;updateAttention();};$('key-index').onchange=e=>{const k=S.keys[Number(e.target.value)];for(let i=0;i<2;i++){const id=i?'ky':'kx';$(id).value=k[i];$(id+'-out').textContent=k[i];}};mountRange('kx',v=>{S.keys[Number($('key-index').value)][0]=v;updateAttention();});mountRange('ky',v=>{S.keys[Number($('key-index').value)][1]=v;updateAttention();});let drag=null;const svg=$('vector-canvas');svg.onpointerdown=e=>{const target=e.target.closest('[data-vector]');if(!target)return;drag=target.dataset.vector;svg.setPointerCapture(e.pointerId);e.preventDefault();};svg.onpointermove=e=>{if(drag===null)return;const point=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse()),px=point.x,py=point.y,v=[Math.max(-2,Math.min(2,(px-200)/61)),Math.max(-2,Math.min(2,(155-py)/61))].map(x=>Math.round(x*20)/20);if(drag==='q'){S.q=v;for(let i=0;i<2;i++){const id=i?'qy':'qx';$(id).value=v[i];$(id+'-out').textContent=v[i];}}else{S.keys[Number(drag)]=v;$('key-index').value=drag;for(let i=0;i<2;i++){const id=i?'ky':'kx';$(id).value=v[i];$(id+'-out').textContent=v[i];}}updateAttention();};svg.onpointerup=()=>drag=null;svg.onpointercancel=()=>drag=null;};
const BLOCKS=[
 ['x','Token + position','E[token] + P[position]','Two learned vectors are added for each position. This is the residual stream entering the block.'],
 ['n1','Normalize features','LayerNorm(x)','Normalize across features at each position, then apply learned scale and offset. No information is mixed between positions here.'],
 ['q','Project queries','Q = norm(x) × Wq + bq','Queries are learned projections of the current representation. Keys and values are separate projections of the same normalized input.'],
 ['k','Project keys','K = norm(x) × Wk + bk','Each key provides a vector against which queries can score similarity.'],
 ['v','Project values','V = norm(x) × Wv + bv','Value vectors contain the information that will be mixed. They do not decide the mixing weights.'],
 ['att','Causal multi-head attention','concat(softmax(Qh Khᵀ / √dh + mask) Vh)','Each head mixes only permitted earlier and current positions. The head outputs are concatenated.'],
 ['mixed','Project head outputs','attention × Wo + bo','Mix information across the concatenated heads with another learned linear projection.'],
 ['res1','Add the first shortcut','x + projected_attention','Add the original input back. Gradients can follow both the shortcut and attention paths.'],
 ['n2','Normalize again','LayerNorm(residual₁)','Another independent LayerNorm prepares the input to the feed-forward network.'],
 ['ff','Expand + activate','GELU(norm(residual₁) × Wf + bf)','At each position independently, expand to four times the width and apply a nonlinear activation.'],
 ['projected','Project back down','expanded × Wp + bp','Return the feature vector to the model width. The same feed-forward network is used at every position.'],
 ['res2','Add the second shortcut','residual₁ + feed_forward_output','The second shortcut adds the transformed features into the residual stream.'],
 ['final','Final normalization','LayerNorm(residual₂)','Normalize the final representation before the vocabulary projection.'],
 ['logits','Predict vocabulary scores','final × Wout + bout','One unnormalized score per vocabulary character at each position. The last row predicts the next character.'],
];
views[6]=()=>`<div class="field"><label for="block-prompt">Input context</label><div class="row"><input id="block-prompt" class="grow" type="text" value="${esc(S.prompt)}" maxlength="80"><button class="btn secondary" id="block-run" data-ready>Run forward pass</button></div></div><div class="grid">${card('One decoder block','LIVE SHAPES','<div id="block-list" class="block-list"></div>')}${card('Follow the computation','LIVE ACTIVATIONS','<div id="block-detail"><p class="loading">Running the model…</p></div>')}</div>`;
function updateBlock(){if(!S.inspect||!$('block-list'))return;const r=S.inspect,t=r.trace;$('block-list').innerHTML=BLOCKS.map(([id,title],i)=>`<button class="block-step ${S.selectedBlock===id?'active':''}" data-block="${id}"><span class="step-icon">${String(i+1).padStart(2,'0')}</span>${title}<span class="shape">${t[id].rows} × ${t[id].cols}</span></button>`).join('');const [id,title,formula,explain]=BLOCKS.find(x=>x[0]===S.selectedBlock),v=t[id];$('block-detail').innerHTML=`<div class="overline">${title.toUpperCase()}</div><div class="formula">${formula}</div><p class="muted mt">${explain}</p><div class="stat-grid"><div class="stat"><strong>${v.rows}</strong><span>POSITIONS</span></div><div class="stat"><strong>${v.cols}</strong><span>FEATURES</span></div><div class="stat"><strong>${v.rows*v.cols}</strong><span>VALUES</span></div></div><div class="tensor-label">LAST POSITION · INPUT CHARACTER ${esc(JSON.stringify(r.chars.at(-1)))}</div>${matrixRow(v.last)}<p class="source-note">Showing the final row, rounded to two decimals. Positive values are green; negative values are orange. This is a forward pass: no weights change.</p>${id==='att'?`<div class="note">${S.config.heads} heads × ${S.config.dim/S.config.heads} dimensions per head = ${S.config.dim} concatenated dimensions.</div>`:''}<button class="text-button mt" data-go="10">Inspect the attention matrices ↗</button>`;document.querySelectorAll('[data-block]').forEach(b=>b.onclick=()=>{S.selectedBlock=b.dataset.block;updateBlock();});}
mounts[6]=()=>{const run=async()=>{if(!modelGuard())return;S.prompt=$('block-prompt').value;try{const r=await inspect(S.prompt);if(S.lesson!==6)return;S.inspect=r;updateBlock();}catch(e){if(S.lesson===6){$('block-list').innerHTML='';$('block-detail').innerHTML=`<p class="note orange">${esc(e.message)}</p>`;}}};$('block-run').onclick=run;$('block-prompt').onkeydown=e=>{if(e.key==='Enter')run();};run();};
views[7]=()=>`<div class="grid">${card('Adjust the logits','5-TOKEN SANDBOX',`<p class="small">Imagine five possible next characters. The correct target is <strong>o</strong>. Move the scores; they do not need to add up to anything.</p>${['w','o','d','s','␠'].map((x,i)=>range('logit-'+i,`Score for ${x}${i===1?' · target':''}`,-4,5,.1,S.toyLogits[i])).join('')}`)}${card('Watch the loss','CROSS-ENTROPY','<div id="loss-results"></div>')}</div>`;
function updateLoss(){const p=probabilities(S.toyLogits),loss=-Math.log(p[1]);$('loss-results').innerHTML=`<div class="overline">NEXT-CHARACTER PROBABILITIES</div>${bars(p,['w','o','d','s',' '],5)}<div class="subtle-divider"></div><div class="overline">LOSS ON THE CORRECT TARGET “o”</div><div class="metric-big">${loss.toFixed(3)} <span class="small">nats</span></div><div class="formula">−ln(${p[1].toFixed(5)}) = ${loss.toFixed(3)}<br>gradient for “o” = p(o) − 1<br>= ${(p[1]-1).toFixed(4)}</div><p class="source-note">The negative target gradient says increasing the “o” logit would reduce this loss. The actual model averages loss over all target positions.</p>`;}
mounts[7]=()=>{updateLoss();S.toyLogits.forEach((_,i)=>mountRange('logit-'+i,v=>{S.toyLogits[i]=v;updateLoss();}));};
views[8]=()=>`<div class="grid">${card('Find the bottom of the curve','ONE-WEIGHT SANDBOX',`<svg id="gradient-plot" class="loss-chart" viewBox="0 0 520 290" role="img" aria-label="Quadratic loss curve with current parameter position"></svg>${range('toy-weight','Weight w',-4,6,.1,S.toyW)}${range('toy-lr','Learning rate η',.05,1.2,.05,S.toyLR)}<div class="row"><button class="btn" id="gradient-step">Take a gradient step</button><button class="btn secondary" id="gradient-reset">Reset</button></div>`)}${card('Follow one update','PLAIN GRADIENT DESCENT','<div id="gradient-results"></div><div class="note mt">The real training room uses Adam. It tracks moving averages of gradients and squared gradients to adapt the update for every weight.</div><button class="text-button mt" data-go="9">Try the real optimizer ↗</button>')}</div>`;
function updateGradient(){const w=S.toyW,loss=(w-1)**2,grad=2*(w-1),next=w-S.toyLR*grad;const x=v=>45+(v+4)*43,y=v=>245-v*5.5;let path='';for(let t=-4;t<=6.01;t+=.1)path+=(path?'L':'M')+x(t)+','+y((t-1)**2);$('gradient-plot').innerHTML=`${[0,10,20,30,40].map(n=>`<line x1="45" x2="485" y1="${y(n)}" y2="${y(n)}" stroke="#e0e8ec"/><text x="35" y="${y(n)+4}" text-anchor="end" class="chart-label">${n}</text>`).join('')}<path d="${path}" fill="none" stroke="#167657" stroke-width="2.5"/>${[-4,-2,0,2,4,6].map(n=>`<text x="${x(n)}" y="270" text-anchor="middle" class="chart-label">${n}</text>`).join('')}<circle cx="${x(w)}" cy="${y(loss)}" r="8" fill="#df8351" stroke="white" stroke-width="3"/><text x="260" y="289" text-anchor="middle" class="chart-label">weight w</text><text x="45" y="18" class="chart-label">loss</text>`;$('gradient-results').innerHTML=`<div class="formula">loss L(w) = (w − 1)²<br>gradient = 2(w − 1)<br><br>w = ${w.toFixed(4)}<br>loss = ${loss.toFixed(4)}<br>gradient = ${grad.toFixed(4)}<br><br>next w = w − η × gradient<br>= ${next.toFixed(4)}</div><p class="small mt">${S.toySteps} steps taken. ${S.toyLR>1?'This learning rate makes the error grow on this curve. Try a smaller value.':S.toyLR===1?'At this rate the weight oscillates with no improvement.':'The minimum is at w = 1. Each step follows the local slope toward it.'}</p>`;}
mounts[8]=()=>{updateGradient();mountRange('toy-weight',v=>{S.toyW=v;updateGradient();});mountRange('toy-lr',v=>{S.toyLR=v;updateGradient();});$('gradient-step').onclick=()=>{const next=S.toyW-S.toyLR*2*(S.toyW-1);if(next< -4||next>6){notice('The next step leaves the plotted range. The update is diverging — reduce the learning rate.');return;}S.toyW=next;S.toySteps++;$('toy-weight').value=next;$('toy-weight-out').textContent=fmt(next);updateGradient();};$('gradient-reset').onclick=()=>{S.toyW=-2;S.toySteps=0;render();};};
views[9]=()=>`<div class="grid">${card('Learning in real time','REAL TRAINING',`<div id="train-metrics"></div><svg id="training-chart" class="loss-chart" viewBox="0 0 620 320" role="img" aria-label="Training and held-out cross-entropy loss by optimizer step"></svg><div class="legend"><span><i></i>Training text</span><span><i class="val"></i>Held-out text</span><span><i class="baseline"></i>Uniform baseline</span></div><p class="source-note">Loss in nats per character. Lower is better. Evaluated on fixed windows every 10 steps. The held-out curve may rise as the poem is memorized.</p><div id="train-progress"></div>`)}${card('Control the experiment','ON YOUR DEVICE',`${select('train-lr','Learning rate',[[.0003,'0.0003 · cautious'],[.001,'0.001 · gentle'],[.003,'0.003 · default'],[.01,'0.01 · aggressive']],S.trainLR)}${select('train-steps','Steps to run',[[10,'10 · quick check'],[100,'100 · first experiment'],[500,'500 · learn patterns'],[1000,'1,000 · watch for overfitting']],S.trainSteps)}<div class="row"><button class="btn" id="train-start" data-idle>▶ Train model</button><button class="btn secondary" id="train-one" data-idle>1 step</button><button class="btn secondary" id="train-stop" data-stop>Pause</button></div><div class="subtle-divider"></div><div id="train-config"></div><div class="row mt"><button class="text-button" id="train-reset" data-idle>Reset to random weights</button><button class="text-button" data-go="1">Change model recipe</button></div><div class="note mt">Try the repeating-pattern dataset to see fast, clean learning. The poem is a harder test with very little data.</div><button class="btn secondary mt" id="load-example" data-idle>Load a trained poem example</button><p class="source-note">The bundled 1,200-step checkpoint was trained by this code and shows overfitting: training loss is low while held-out loss is high. Loading it replaces your current model. Training and exports stay on this device; reloading the page starts fresh.</p>`)} </div><div id="witness" class="mt"></div>`;
function lossChart(){const svg=$('training-chart');if(!svg)return;const data=S.history,base=Math.log(S.data?.vocab.length||40),maxY=Math.max(base+.4,...data.flatMap(x=>[x.train,x.validation]))*1.08,maxX=Math.max(100,...data.map(x=>x.step));const X=s=>48+s/maxX*540,Y=l=>271-l/maxY*238;let html='';for(let i=0;i<=4;i++){const v=maxY*i/4;html+=`<line x1="48" x2="588" y1="${Y(v)}" y2="${Y(v)}" stroke="#e3eaed"/><text x="37" y="${Y(v)+4}" text-anchor="end" class="chart-label">${v.toFixed(1)}</text>`;}for(let i=0;i<=4;i++)html+=`<text x="${X(maxX*i/4)}" y="294" text-anchor="middle" class="chart-label">${Math.round(maxX*i/4)}</text>`;html+=`<text x="318" y="317" text-anchor="middle" class="chart-label">optimizer steps</text><text x="48" y="17" class="chart-label">cross-entropy loss ↓</text><line x1="48" x2="588" y1="${Y(base)}" y2="${Y(base)}" stroke="#a9b7bf" stroke-dasharray="4 5"/>`;for(const [key,color] of [['train','#167657'],['validation','#df8351']]){const path=data.map((p,i)=>(i?'L':'M')+X(p.step)+','+Y(p[key])).join(' ');html+=`<path d="${path}" stroke="${color}" stroke-width="2.5" fill="none"/>`;if(data.length){const p=data.at(-1);html+=`<circle cx="${X(p.step)}" cy="${Y(p[key])}" r="4" fill="${color}"/>`;}}if(data.length<2)html+='<text x="318" y="155" text-anchor="middle" class="chart-label">Run a few steps to draw the learning curves.</text>';svg.innerHTML=html;}
function updateTraining(){if(!S.data||!$('train-metrics'))return;const last=S.history.at(-1)||{},step=S.data.step;$('train-metrics').innerHTML=`<div class="stat-grid"><div class="stat"><strong>${step.toLocaleString()}</strong><span>OPTIMIZER STEPS</span></div><div class="stat"><strong>${fmt(last.train)}</strong><span>TRAIN LOSS</span></div><div class="stat"><strong>${fmt(last.validation)}</strong><span>HELD-OUT LOSS</span></div></div>`;lossChart();const p=S.progress;$('train-progress').innerHTML=p?`<div class="train-progress"><i style="width:${100*p.completed/p.requested}%"></i></div><div class="row between"><span class="small">${S.busy==='train'?'Running':p.completed===p.requested?'Run complete':'Paused'} · ${p.completed}/${p.requested} steps</span><span class="small">${fmt(p.elapsed,1)}s · ${p.elapsed>0?fmt(p.completed/p.elapsed,1):'—'} steps/s</span></div>`:'';$('train-config').innerHTML=`<p class="small"><strong>${S.data.count.toLocaleString()}</strong> trainable parameters<br>${S.config.dim} dimensions · ${S.config.heads} heads · 1 decoder block<br>${S.config.context} characters/window · 4 windows/update<br>${(step*4*S.config.context).toLocaleString()} target-token presentations<br>Adam · gradient norm clipped at 1 · seed ${S.config.seed}</p><p class="small">Held-out character perplexity: <strong>${fmt(Math.exp(last.validation),2)}</strong></p>`;
  const w=S.learned;$('witness').innerHTML=w?card('One weight, one real update','LIVE BACKPROP',`<p class="small">Query projection Wq[0,0] at step ${step}. Its gradient is averaged over the batch; Adam uses the clipped gradient plus its running moments.</p><div class="inline-fields"><div class="formula">before<br><strong>${fmt(w.before,7)}</strong></div><div class="formula">gradient (before clipping)<br><strong>${fmt(w.gradient,7)}</strong></div><div class="formula">after<br><strong>${fmt(w.after,7)}</strong></div></div><p class="source-note">Global gradient norm: ${fmt(p.gradNorm,3)} · ${p.clipped?'clipped to 1':'no clipping needed'}. The change is not simply −learning-rate × gradient because this is Adam.</p>`):'';syncButtons();
}
mounts[9]=()=>{updateTraining();$('train-lr').onchange=e=>S.trainLR=Number(e.target.value);$('train-steps').onchange=e=>S.trainSteps=Number(e.target.value);$('train-start').onclick=()=>train(Number($('train-steps').value));$('train-one').onclick=()=>train(1);$('train-stop').onclick=stop;$('train-reset').onclick=()=>{S.progress=null;initialize(S.text,S.config);syncButtons();};$('load-example').onclick=async()=>{try{const response=await fetch(new URL('./poem-checkpoint.json',import.meta.url));if(!response.ok)throw Error('Checkpoint could not be loaded.');const snapshot=await response.json();S.modelPending=true;modelRequest=send('load',{snapshot});syncButtons();notice('Loading a model trained by the tutorial’s own engine.');}catch(e){notice(e.message,true);}};};
views[10]=()=>`<div class="field"><label for="inspect-prompt">Context to inspect</label><div class="row"><input id="inspect-prompt" class="grow" type="text" maxlength="160" value="${esc(S.prompt)}"><button class="btn" id="inspect-run" data-ready>Inspect prediction</button></div></div><div class="grid">${card('Who attends to whom?','LIVE ATTENTION',`<div class="inline-fields">${select('inspect-head','Attention head',Array.from({length:S.config.heads},(_,i)=>[i,`Head ${i+1}`]),S.selectedHead)}<div class="field"><label for="inspect-row">Query row</label><select id="inspect-row"></select></div></div><div id="heatmap-content"></div><p class="source-note">Rows ask; columns provide information. Darker green = larger weight. Hatching = future position, always masked. Scroll horizontally for long contexts.</p>`)}${card('What comes next?','LAST-POSITION OUTPUT','<div id="inspect-probabilities"><p class="loading">Running a forward pass…</p></div><div class="subtle-divider"></div><div id="attention-row-detail"></div>')}</div>`;
function updateHeatmap(){const r=S.inspect;if(!r||!$('heatmap-content'))return;const N=r.chars.length,h=Math.min(S.selectedHead,r.heads-1);S.selectedHead=h;S.selectedRow=S.selectedRow<0?N-1:Math.min(S.selectedRow,N-1);$('inspect-row').innerHTML=r.chars.map((c,i)=>`<option value="${i}"${S.selectedRow===i?' selected':''}>${i} · ${esc(visible(c))}</option>`).join('');const A=r.attention.slice(h*N*N,(h+1)*N*N);$('heatmap-content').innerHTML=`<div class="small">Showing ${N} most recent characters · key / value positions →</div><div class="heatmap-wrap"><div class="heatmap" style="grid-template-columns:24px repeat(${N},22px)"><span></span>${r.chars.map((c,i)=>`<span class="heat-label" title="Column ${i}: ${esc(JSON.stringify(c))}">${esc(visible(c))}</span>`).join('')}${r.chars.map((c,i)=>`<span class="heat-label" title="Query ${i}">${esc(visible(c))}</span>${r.chars.map((_,j)=>i<j?`<span class="heat-cell future" title="Masked future position" aria-label="Query ${i}, key ${j}: masked"></span>`:`<button class="heat-cell ${i===S.selectedRow?'selected':''}" data-heat-row="${i}" title="Query ${i} → key ${j}: ${(A[i*N+j]*100).toFixed(2)}%" aria-label="Query ${i}, key ${j}: ${(A[i*N+j]*100).toFixed(2)} percent" style="background:rgba(22,118,87,${.08+.92*A[i*N+j]})"></button>`).join('')}`).join('')}</div></div>`;
  const p=probabilities(r.logits);$('inspect-probabilities').innerHTML=`<p class="small">Top 8 next-character probabilities for <code>${esc(r.chars.map(visible).join(''))}</code>, at temperature 1 without filtering.</p>${bars(p,S.data.vocab)}<p class="source-note">The top 8 are shown; the full vocabulary distribution sums to 100%.</p>`;const row=A.slice(S.selectedRow*N,(S.selectedRow+1)*N),sum=row.reduce((a,b)=>a+b,0);$('attention-row-detail').innerHTML=`<div class="overline">SELECTED QUERY · ${S.selectedRow}: ${esc(JSON.stringify(r.chars[S.selectedRow]))}</div>${bars(row,r.chars.map((c,i)=>`${i}:${visible(c)}`),Math.min(N,6))}<p class="source-note">Row sum: ${sum.toFixed(6)}. Displaying the largest weights; repeated characters still occupy distinct positions.</p>`;document.querySelectorAll('[data-heat-row]').forEach(b=>b.onclick=()=>{S.selectedRow=Number(b.dataset.heatRow);updateHeatmap();});}
mounts[10]=()=>{const run=async()=>{if(!modelGuard())return;S.prompt=$('inspect-prompt').value;try{const r=await inspect(S.prompt);if(S.lesson!==10)return;S.inspect=r;S.selectedRow=-1;updateHeatmap();}catch(e){if(S.lesson===10){$('heatmap-content').innerHTML='';$('attention-row-detail').innerHTML='';$('inspect-probabilities').innerHTML=`<p class="note orange">${esc(e.message)}</p>`;}}};$('inspect-run').onclick=run;$('inspect-prompt').onkeydown=e=>{if(e.key==='Enter')run();};$('inspect-head').onchange=e=>{S.selectedHead=Number(e.target.value);updateHeatmap();};$('inspect-row').onchange=e=>{S.selectedRow=Number(e.target.value);updateHeatmap();};run();};
views[11]=()=>`<div class="grid">${card('A continuation, character by character','LIVE GENERATION',`<div id="generation-output" class="output-text"></div><div class="subtle-divider"></div><div class="row"><button class="btn mint" id="generate-start" data-idle>Generate text</button><button class="btn outline" id="generate-one" data-idle>+1 character</button><button class="btn outline" id="generate-stop" data-stop>Stop</button></div><p id="generation-context" class="small mt"></p>`,true)}${card('How should it choose?','SAMPLING',`<div class="field"><label for="gen-prompt">Start with a prompt</label><input id="gen-prompt" type="text" maxlength="200" value="${esc(S.genPrompt)}"></div>${range('gen-temp','Temperature',0,1.8,.05,S.temperature)}${range('gen-topk','Top-k · 0 keeps all',0,S.data?.vocab.length||45,1,S.topK)}<div class="inline-fields">${select('gen-length','New characters',[[40,'40'],[160,'160'],[300,'300']],S.genLength)}<div class="field"><label for="gen-seed">Sampling seed</label><input id="gen-seed" type="number" min="0" max="4294967295" value="${S.genSeed}"></div></div><p class="small">Temperature 0: greedy choice. Below 1: more predictable. Above 1: more varied, often less coherent.</p><div id="generation-bars"></div>`)} </div><div class="card mt"><div class="row between"><div class="grow"><h3>Keep what you trained</h3><p class="small">A checkpoint contains the text, model recipe, weights, training history, and Adam state. Download it before closing or refreshing this page.</p></div><div class="row"><button class="btn secondary" id="export-model" data-idle>↓ Export model</button><button class="btn secondary" id="import-model" data-idle>↑ Import model</button><input type="file" id="import-file" accept="application/json,.json" hidden></div></div><p class="source-note">Checkpoints include your training text. Imports are validated and stay local. Architecture and tokenizer must match the weights; this format is specific to Attention Lab.</p></div>`;
function updateGeneration(){if(!$('generation-output'))return;const output=S.output||S.genPrompt,prefix=output.startsWith(S.genPrompt)?S.genPrompt:'';$('generation-output').innerHTML=`<span class="prompt">${esc(prefix)}</span><span class="new">${esc(output.slice(prefix.length))}</span>${S.busy==='generate'?'<span class="generation-caret" aria-hidden="true"></span>':''}`;$('generation-context').textContent=S.genContext?`Last prediction used ${S.genContext.length} characters of context. The window keeps at most ${S.config.context}.`:'Your prompt is gray. Generated text will appear in green.';if(S.genDistribution)$('generation-bars').innerHTML=`<div class="overline">DISTRIBUTION USED FOR THE LAST DRAW</div>${bars(S.genDistribution,S.data.vocab,5)}`;else $('generation-bars').innerHTML='';syncButtons();}
mounts[11]=()=>{updateGeneration();mountRange('gen-temp',v=>S.temperature=v);mountRange('gen-topk',v=>S.topK=v);$('gen-prompt').oninput=e=>{S.genPrompt=e.target.value;S.output='';S.genDistribution=null;S.genContext=null;updateGeneration();};$('gen-length').onchange=e=>S.genLength=Number(e.target.value);$('generate-start').onclick=()=>generate(Number($('gen-length').value));$('generate-one').onclick=()=>generate(1);$('generate-stop').onclick=stop;$('export-model').onclick=()=>{if(modelGuard())send('export');};$('import-model').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>8e6){notice('This checkpoint is too large. The maximum size is 8 MB.',true);return;}try{const snapshot=JSON.parse(await file.text());S.modelPending=true;modelRequest=send('load',{snapshot});syncButtons();}catch{notice('Could not read that JSON model file.',true);}};};
const CASES=[['Teach the model to follow a question-and-answer format.','sft','Instruction tuning trains on examples of desired input–response behavior.'],['Answer using a document published this morning.','rag','Retrieval can put relevant new passages into the context without changing the model’s weights.'],['Prefer a helpful answer over a misleading answer.','preference','Preference optimization learns from comparisons of better and worse responses.'],['Reduce memory needed to serve the trained model.','quant','Quantization represents weights (and sometimes activations) with fewer bits. It can change accuracy and needs evaluation.'],['Calculate an exact result or query a live database.','tools','Tool use delegates an operation to an external program, then supplies its result to the model.']];
views[12]=()=>`<div class="grid">${card('Choose the right next step','APPLY THE IDEAS',CASES.map(([question],i)=>`<div class="case-card"><p>${question}</p><select data-case="${i}" aria-label="Method for: ${question}"><option value="">Choose a method…</option><option value="sft">Instruction tuning</option><option value="rag">Retrieval-augmented generation</option><option value="preference">Preference optimization</option><option value="quant">Quantization</option><option value="tools">Tool use</option></select><div id="case-feedback-${i}" class="case-feedback" aria-live="polite"></div></div>`).join(''))}${card('What scales up?','THE SAME CORE',`<p class="muted">The essential prediction loop remains. Larger systems add capacity, data diversity, training stages, and serving infrastructure.</p><ol class="help-list"><li><strong>Prepare data:</strong> provenance, permission, cleaning, deduplication, tokenization, separate evaluations.</li><li><strong>Pretrain:</strong> optimize next-token loss across large, diverse corpora with many layers and batches.</li><li><strong>Adapt:</strong> instruction examples, full fine-tuning or parameter-efficient adapters, preference learning.</li><li><strong>Evaluate:</strong> unseen tasks, factuality, robustness, bias, safety, latency, and memory.</li><li><strong>Serve:</strong> serialize weights, choose precision, batch requests, cache attention keys and values.</li><li><strong>Augment:</strong> retrieval and tools add external information and actions.</li><li><strong>Monitor:</strong> find failure modes, review feedback, and evaluate future updates.</li></ol><div class="note">Prompting changes the context. Fine-tuning changes weights. Retrieval adds information. Sampling chooses among predictions. These are different operations.</div><button class="text-button mt" data-action="sources">Read the original papers ↗</button>`)} </div><div class="card mt"><h3>This implementation, precisely</h3><div class="table-scroll"><table class="comparison"><thead><tr><th>Component</th><th>In this tutorial</th><th>Common larger-system alternatives</th></tr></thead><tbody><tr><td>Tokenizer</td><td>Unicode characters, vocabulary ≤160</td><td>Byte/subword vocabularies with special tokens</td></tr><tr><td>Architecture</td><td>1 decoder block, 1–4 attention heads</td><td>Many blocks, grouped-query attention, mixture-of-experts</td></tr><tr><td>Positions</td><td>Learned absolute embeddings, up to 32 characters</td><td>Rotary positions and longer contexts</td></tr><tr><td>FFN / normalization</td><td>GELU, width 4d, pre-LayerNorm</td><td>Gated FFNs, RMSNorm</td></tr><tr><td>Optimization</td><td>Adam, fixed learning rate, global norm clipping</td><td>AdamW, schedules, larger batches, distributed training</td></tr><tr><td>Numerics</td><td>Float64 CPU arrays, handwritten autodiff</td><td>GPU accelerators, mixed precision, optimized kernels</td></tr><tr><td>Generation</td><td>Greedy / temperature / top-k; full recomputation</td><td>Top-p, KV caching, batching, speculative decoding</td></tr><tr><td>Storage</td><td>Local JSON checkpoint</td><td>Sharded weight formats and deployment systems</td></tr></tbody></table></div></div>`;
mounts[12]=()=>document.querySelectorAll('[data-case]').forEach(s=>s.onchange=()=>{const i=Number(s.dataset.case),correct=s.value===CASES[i][1];$('case-feedback-'+i).textContent=s.value?(correct?'Correct. '+CASES[i][2]:'That method serves a different purpose. Try another.'):'';$('case-feedback-'+i).style.color=correct?'var(--green)':'#a5542b';});

document.addEventListener('click',e=>{const goButton=e.target.closest('[data-go]');if(goButton){go(Number(goButton.dataset.go));return;}const quiz=e.target.closest('[data-quiz]');if(quiz){const choice=Number(quiz.dataset.quiz),correct=choice===LESSONS[S.lesson].answer;quiz.classList.add(correct?'correct':'wrong');$('quiz-feedback').textContent=correct?'Exactly. You have the key idea.':'Not quite. Revisit the experiment, then try again.';if(correct){S.checked.add(S.lesson);const item=document.querySelector('.nav-link.active .nav-number');if(item)item.textContent='✓';}return;}if(e.target.closest('[data-action="sources"]'))$('sources-dialog').showModal();});
function syncNavigation(){const hidden=window.matchMedia('(max-width:700px)').matches&&!$('sidebar').classList.contains('open');$('sidebar').inert=hidden;$('sidebar').setAttribute('aria-hidden',String(hidden));}
window.matchMedia('(max-width:700px)').addEventListener('change',syncNavigation);
$('menu-toggle').onclick=()=>{const open=$('sidebar').classList.toggle('open');$('menu-toggle').setAttribute('aria-expanded',String(open));syncNavigation();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('sidebar').classList.remove('open');$('menu-toggle').setAttribute('aria-expanded','false');syncNavigation();}});
$('glossary-button').onclick=()=>$('glossary-dialog').showModal();$('close-glossary').onclick=()=>$('glossary-dialog').close();
$('reference-button').onclick=()=>$('sources-dialog').showModal();$('close-sources').onclick=()=>$('sources-dialog').close();$('sources-dialog').onclick=e=>{if(e.target===$('sources-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
$('references').innerHTML=REFERENCES.map(([title,description,url])=>`<div class="reference"><a href="${url}" target="_blank" rel="noopener noreferrer">${title} ↗</a><p>${description}</p></div>`).join('');
window.addEventListener('hashchange',()=>{const n=Number(location.hash.match(/^#lesson-(\d+)$/)?.[1]);if(Number.isInteger(n)&&n>=0&&n<LESSONS.length&&n!==S.lesson){S.lesson=n;render();}});
const first=Number(location.hash.match(/^#lesson-(\d+)$/)?.[1]);if(Number.isInteger(first)&&first>=0&&first<LESSONS.length)S.lesson=first;
render();syncNavigation();
// Optional progressive enhancement: the same navigation and status used by the UI.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [
 {name:'read_tutorial_state',title:'Read tutorial state',description:'Read the current lesson, local model configuration, training progress and latest measured losses.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({lesson:S.lesson+1,title:LESSONS[S.lesson].short,ready:!!S.data&&!S.modelPending,busy:S.busy,config:S.config,parameters:S.data?.count,step:S.data?.step,latestLoss:S.history.at(-1)})},
 {name:'navigate_tutorial_lesson',title:'Open a tutorial lesson',description:'Navigate to a lesson numbered 1 through 13. This changes the visible lesson without changing model weights.',inputSchema:{type:'object',properties:{lesson:{type:'integer',minimum:1,maximum:13}},required:['lesson'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.lesson)||input.lesson<1||input.lesson>13||Object.keys(input).some(k=>k!=='lesson'))throw Error('lesson must be an integer from 1 through 13.');go(input.lesson-1);return {lesson:S.lesson+1,title:LESSONS[S.lesson].short};}}
]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
